import {YAW,TASKS,LABELS,round,clamp,cm360,validProfile,seeded,makePlan,analyze,scoreTrial,project,angularDistance} from './engine.js';
import {isTracking,TASK_INFO,PROTOCOLS,planTasks,summarizeTrials} from './engine.js';
import {createTelemetry,beginAcquisition,observeMovement,recordHit,recordSample,makeMotion,updateTarget,spawn} from './training.js';
import * as V from './views.js';
const $=s=>document.querySelector(s), fmt=(n,p=3)=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:p}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEFAULT={dpi:800,sens:.35,calibration:1,sound:true};
function read(key,fallback){try{return JSON.parse(localStorage.getItem('iamira.'+key))??fallback;}catch{return fallback;}}
let profile=read('profile',DEFAULT);if(!validProfile(profile)) profile={...DEFAULT};
let history=read('history',[]);if(!Array.isArray(history))history=[];history=history.filter(h=>h&&h.plan?.rounds&&Array.isArray(h.trials)&&h.result?.rows);
let practiceHistory=read('practiceHistory',[]);if(!Array.isArray(practiceHistory))practiceHistory=[];practiceHistory=practiceHistory.filter(h=>h?.trial&&TASKS.includes(h.trial.task)&&h.profile);
let pending=read('pending',null);if(pending&&(!pending.plan?.rounds||!Array.isArray(pending.trials)||!validProfile(pending.plan.profile)))pending=null;
let lastResult=null, toastTimer, refineRequested=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function save(key,value){try{localStorage.setItem('iamira.'+key,JSON.stringify(value));return true;}catch{toast('Não foi possível salvar neste navegador. Exporte seus resultados.');return false;}}
const date=d=>new Date(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
const metric=(title,value,unit,foot,green=false)=>`<div class="metric"><div class="metric-label">${title}<span>↗</span></div><div class="number">${value}<small>${unit}</small></div><div class="metric-foot ${green?'green':''}">${foot}</div></div>`;
const heading=(eyebrow,title,description)=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="date-chip"><span>●</span> VALORANT · HIPFIRE</div></div>`;
function dashboard(){return V.dashboard({profile,history,pending,practiceHistory});}
function profileFields(){return `<div class="form-grid"><label class="field">DPI do mouse<input name="dpi" type="number" min="100" max="32000" step="1" value="${profile.dpi}" required><small>Consulte o software do seu mouse. O navegador não detecta DPI.</small></label><label class="field">Sensibilidade no Valorant<input name="sens" type="number" min="0.01" max="5" step="0.001" value="${profile.sens}" required><small>O valor em Configurações → Mouse → Sensibilidade: Mira.</small></label></div>`;}
function diagnostic(){return V.diagnostic({pending,profileFields,refine:refineRequested,profile});}
function practice(task){return V.practice({task,profile,practiceHistory});}
function historyPage(){return V.historyPage({history});}
function settings(){return `${heading('CONFIGURAÇÕES','Perfil e calibração','Confira os valores de entrada e a correspondência física do movimento.')}<div class="split"><form id="settings-form" class="panel setup-panel"><h2>Perfil do jogador</h2>${profileFields()}<label class="field" style="margin-top:20px">Fator de calibração do navegador<input name="calibration" type="number" min="0.1" max="10" step="0.001" value="${profile.calibration}" required><small>Padrão 1. Ajuste com a ferramenta ao lado se a distância física não coincidir.</small></label><label style="display:flex;gap:10px;font-size:12px;margin-top:20px"><input name="sound" type="checkbox" ${profile.sound?'checked':''}> Som discreto ao acertar</label><button class="btn primary" type="submit">Salvar configurações ✓</button><p class="error" id="form-error" role="alert"></p></form><section class="panel"><h2>Confira o movimento real</h2><p>O navegador pode interpretar o mouse de forma diferente do jogo. A calibração compara o giro com uma distância medida no mousepad.</p><div class="calibration-value">${fmt(cm360(profile.dpi,profile.sens),1)} <small style="font-size:14px">cm / 360°</small></div><p>Este é o giro teórico do seu perfil. Para medir, mova o mouse horizontalmente por uma distância conhecida, sem levantá-lo.</p><div class="actions"><button class="btn secondary" data-action="calibrate">Calibrar movimento ↗</button></div><div class="notice">Use o navegador em 100% de zoom. A entrada sem aceleração será solicitada quando disponível. Confirme também o cm/360° no Valorant.</div></section></div><div class="panel" style="margin-top:22px"><h2>Seus dados ficam com você</h2><p>Perfil, treinos, sessões e histórico usam o armazenamento local deste navegador. Não há envio de telemetria. Limpar os dados do navegador apaga o histórico; exporte uma cópia antes.</p><div class="actions"><button class="btn ghost" data-action="export-all">Exportar dados ↓</button><button class="btn ghost" data-action="clear-history">Apagar diagnósticos e treinos</button></div></div>`;}
function method(){return V.method();}
function results(record){if(!record)return historyPage();lastResult=record;return V.results(record);}
function render(){const [page='dashboard',arg]=(location.hash.slice(1)||'dashboard').split('/');const pages={dashboard,diagnostic,practice,history:historyPage,settings,method,result:()=>results(history.find(h=>h.id===arg)||lastResult)};const titles={dashboard:'Visão geral',diagnostic:'Diagnóstico',practice:'Treino livre',history:'Histórico',settings:'Configurações',method:'Como funciona',result:'Sua análise'};$('#main').innerHTML=(pages[page]||dashboard)(arg);$('#page-name').textContent=titles[page]||titles.dashboard;document.querySelectorAll('[data-nav]').forEach(el=>{const on=el.dataset.nav===page;el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
function getProfile(form){const data=new FormData(form),p={...profile,dpi:Number(data.get('dpi')),sens:Number(data.get('sens'))};if(data.has('calibration')){p.calibration=Number(data.get('calibration'));p.sound=data.has('sound');}if(!validProfile(p))throw new Error('Confira o DPI (100–32000), a sensibilidade (0,01–5) e o fator (0,1–10).');return p;}
document.addEventListener('submit',e=>{const f=e.target;if(!['diagnostic-form','practice-form','settings-form'].includes(f.id))return;e.preventDefault();try{if(f.id==='settings-form'){profile=getProfile(f);save('profile',profile);toast('Configurações salvas.');render();}else if(f.id==='diagnostic-form'){if(!canPlay())return;profile=getProfile(f);save('profile',profile);const d=new FormData(f);pending={plan:makePlan(profile,d.get('protocol'),Date.now()>>>0,d.get('range')||'extended'),trials:[],createdAt:new Date().toISOString()};save('pending',pending);refineRequested=false;openDiagnostic();}else{if(!canPlay())return;const d=new FormData(f);openPractice(d.get('task'),Number(d.get('seconds')));}}catch(err){const output=$('#form-error');if(output)output.textContent=err.message;else toast(err.message);}});
function download(data,name){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='settings')location.hash='settings';if(action==='resume'&&canPlay())openDiagnostic();if(action==='discard'){if(confirm('Descartar as rodadas deste diagnóstico? Seu histórico será mantido.')){pending=null;save('pending',null);render();}}if(action==='view-result')location.hash='result/'+el.dataset.id;if(action==='apply-result'&&lastResult?.result.recommendation){profile={...profile,dpi:lastResult.plan.profile.dpi,sens:lastResult.result.recommendation.sens};save('profile',profile);toast('Perfil atualizado. Ajuste o mesmo valor no Valorant.');}if(action==='copy-result'&&lastResult?.result.recommendation){try{await navigator.clipboard.writeText(String(lastResult.result.recommendation.sens));toast('Sensibilidade copiada.');}catch{toast('Valor: '+fmt(lastResult.result.recommendation.sens));}}if(action==='export-result'&&lastResult)download(lastResult,'aimology-diagnostico.json');if(action==='export-all')download({version:2,exportedAt:new Date().toISOString(),profile,history,practiceHistory,pending},'aimology-historico.json');if(action==='clear-history'&&confirm('Apagar todo o histórico de diagnósticos e treinos deste navegador?')){history=[];practiceHistory=[];lastResult=null;save('history',history);save('practiceHistory',practiceHistory);toast('Histórico apagado.');}if(action==='refine-result'&&lastResult?.result.recommendation){if(pending){toast('Conclua ou descarte a sessão em andamento antes de refinar.');location.hash='diagnostic';return;}profile={...profile,dpi:lastResult.plan.profile.dpi,sens:lastResult.result.recommendation.sens};save('profile',profile);refineRequested=true;location.hash='diagnostic';render();const range=$('#diagnostic-form select[name="range"]');if(range)range.value='refine';toast('Perfil atualizado. Confira e inicie o refinamento.');}if(action==='calibrate'&&canPlay())openCalibration();});
function updateDiagnosticPreview(){
  const form=$('#diagnostic-form');if(!form)return;
  const data=new FormData(form),candidateProfile={...profile,dpi:Number(data.get('dpi')),sens:Number(data.get('sens'))},range=data.get('range')||'extended';
  $('#protocol-options').innerHTML=V.protocolOptions(candidateProfile,range,data.get('protocol')||'complete');
  $('#range-preview').innerHTML=V.rangePreview(candidateProfile,range);
}
document.addEventListener('input',e=>{if(e.target.matches('#diagnostic-form input[name="dpi"], #diagnostic-form input[name="sens"]'))updateDiagnosticPreview();});
document.addEventListener('change',e=>{if(e.target.matches('#diagnostic-form select[name="range"]'))updateDiagnosticPreview();if(e.target.id==='analysis-task'&&lastResult){$('#analysis-detail').innerHTML=V.analysisDetail(lastResult,e.target.value);}if(e.target.matches('#practice-form select[name="task"]'))location.hash='practice/'+e.target.value;});
function canPlay(){if(!('requestPointerLock' in HTMLCanvasElement.prototype)||matchMedia('(pointer: coarse)').matches){toast('Para treinar, abra no computador com mouse e um navegador que suporte captura do cursor.');return false;}return true;}

// Training engine: perspective camera, angular targets, relative mouse input.
const canvas=$('#game'),ctx=canvas.getContext('2d'),dialog=$('#arena');
let game=null,frame=0,audioCtx=null,rawStatus='Entrada sem aceleração solicitada; confirme pela calibração';
function beep(){if(!game?.profile.sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=950;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.06);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.06);}catch{}}
function showOverlay(html){$('#arena-overlay').innerHTML=`<div class="overlay-card">${html}</div>`;$('#arena-overlay').classList.remove('hidden');}
function instructions(task){return isTracking(task)?'Acompanhe o alvo sem clicar. Mantenha o centro da mira dentro dele.':task==='switch'?'Acerte apenas o alvo preenchido. Os outros dois indicam possíveis próximas posições.':task==='strafe'?'Acerte o alvo em movimento com o botão esquerdo. Um novo alvo aparece a cada acerto.':'Mova o mouse para mirar e clique com o botão esquerdo. Busque precisão e velocidade.';}
function newGame(mode,trial,prof){return {mode,trial,profile:{...prof},legacy:mode==='diagnostic'&&!(pending.plan.version>=2),phase:'ready',yaw:0,pitch:0,target:{yaw:0,pitch:0,radius:1.1},elapsed:0,countdown:3,shots:0,hits:0,onTargetMs:0,reactionTimes:[],spawnAt:0,path:0,rng:seeded(trial.seed),last:0,flash:0,w:0,h:0,inputMode:rawStatus,calibrationCounts:0,telemetry:createTelemetry(),motion:makeMotion(trial.seed,trial.seconds),lastHUD:0};}
function openDiagnostic(){if(!pending)return;if(pending.trials.length===pending.plan.rounds.length){completeDiagnostic();return;}const t=pending.plan.rounds[pending.trials.length];game=newGame('diagnostic',t,pending.plan.profile);openArena();roundIntro();}
function openPractice(task,seconds){game=newGame('practice',{task,sens:profile.sens,seconds,seed:Date.now()>>>0,rep:0},profile);openArena();roundIntro();}
function openArena(){if(!dialog.open)dialog.showModal();resize();cancelAnimationFrame(frame);game.last=performance.now();frame=requestAnimationFrame(tick);$('#arena-mode').textContent=game.mode==='calibration'?'Calibração':LABELS[game.trial.task];$('#input-mode').textContent=rawStatus;}
function roundIntro(){const diagnostic=game.mode==='diagnostic';showOverlay(`<div class="eyebrow">${diagnostic?'RODADA '+(pending.trials.length+1)+' / '+pending.plan.rounds.length:'TREINO LIVRE'}</div><h2>${LABELS[game.trial.task]}</h2><p>${instructions(game.trial.task)}</p><div class="tags" style="justify-content:center;margin-top:18px"><span>${game.trial.seconds} SEGUNDOS</span><span>3 S DE ADAPTAÇÃO</span>${diagnostic?'':`<span>SENS ${fmt(game.trial.sens)}</span>`}</div><button id="begin-round" class="btn primary">Capturar mouse e começar ↗</button><p style="font-size:10px;margin-top:15px">Esc pausa a rodada. Trocar de aba também pausa.</p>`);$('#begin-round').onclick=startPointer;}
async function startPointer(){if(!game)return;try{if(audioCtx?.state==='suspended')audioCtx.resume();try{await canvas.requestPointerLock({unadjustedMovement:true});rawStatus='Entrada sem aceleração solicitada · confirme pela calibração';}catch(err){if(err.name!=='NotSupportedError')throw err;await canvas.requestPointerLock();rawStatus='Entrada padrão · aceleração pode afetar a equivalência';}if(document.pointerLockElement===canvas)locked();}catch{showLockError();}}
function showLockError(){if(!game)return;showOverlay(`<div class="eyebrow">MOUSE NÃO CAPTURADO</div><h2>Vamos tentar novamente.</h2><p>O navegador bloqueou a captura do mouse. Abra em uma janela própria, clique abaixo e permita a captura. Após usar Esc, aguarde um instante antes de tentar.</p><button id="retry-lock" class="btn primary">Tentar novamente</button>`);$('#retry-lock').onclick=startPointer;}
document.addEventListener('pointerlockerror',()=>{if(game&&document.pointerLockElement!==canvas)showLockError();});
function locked(){if(!game||!['ready','paused'].includes(game.phase))return;$('#arena-overlay').classList.add('hidden');$('#input-mode').textContent=rawStatus;game.inputMode=rawStatus;game.phase=game.mode==='calibration'?'calibrating':'countdown';game.countdown=3;game.last=performance.now();if(game.mode!=='calibration'&&game.elapsed===0)spawnTarget();}
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)locked();else if(game&&['running','countdown','calibrating'].includes(game.phase))pauseGame();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&['running','countdown','calibrating'].includes(game.phase)){pauseGame();document.exitPointerLock();}});
window.addEventListener('blur',()=>{if(game&&['running','countdown','calibrating'].includes(game.phase)){pauseGame();document.exitPointerLock();}});
function pauseGame(){if(!game||game.phase==='paused')return;game.telemetry.pauses++;if(game.mode==='calibration'){finishCalibration();return;}game.phase='paused';$('#countdown').textContent='';showOverlay(`<div class="eyebrow">RODADA PAUSADA</div><h2>Rodada pausada</h2><p>O tempo está parado. Ao voltar, você terá três segundos para se readaptar.</p><div class="actions"><button class="btn primary" id="resume-round">Retomar ↗</button><button class="btn ghost" id="leave-round">Sair do treino</button></div><p style="font-size:10px;margin-top:15px">A rodada atual só é salva quando concluída.</p>`);$('#resume-round').onclick=startPointer;$('#leave-round').onclick=closeArena;}
function resize(){if(!game)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);game.w=rect.width;game.h=rect.height;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
window.addEventListener('resize',resize);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==canvas||!game||!['countdown','running','calibrating'].includes(game.phase))return;if(game.mode==='calibration'){game.calibrationCounts+=e.movementX;return;}const gain=YAW*game.trial.sens*game.profile.calibration;game.yaw=((game.yaw+e.movementX*gain+180)%360+360)%360-180;game.pitch=clamp(game.pitch-e.movementY*gain,-85,85);if(game.phase==='running'){game.path+=Math.hypot(e.movementX*gain,e.movementY*gain);observeMovement(game);}});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('mousedown',e=>{if(e.button!==0||!game||document.pointerLockElement!==canvas)return;if(game.mode==='calibration'&&game.phase==='calibrating'){finishCalibration();return;}if(game.phase!=='running'||isTracking(game.trial.task))return;game.shots++;if(isOnTarget()){game.hits++;recordHit(game);game.reactionTimes.push(game.elapsed-game.spawnAt);game.flash=1;beep();spawnTarget();}else game.flash=-1;});
function spawnTarget(){if(!game.legacy){spawn(game);return;}const g=game,t=g.trial.task;if(t==='tracking'){g.target={yaw:0,pitch:0,radius:1.8};return;}const spread=t==='micro'?5:25,height=t==='micro'?2.7:11;let target;for(let i=0;i<20;i++){target={yaw:(g.rng()*2-1)*spread,pitch:(g.rng()*2-1)*height,radius:t==='micro'?.65:1.5};if(angularDistance(target.yaw,target.pitch,g.target.yaw,g.target.pitch)>(t==='micro'?1.6:8))break;}g.target=target;g.spawnAt=g.elapsed;}
function isOnTarget(){return angularDistance(game.yaw,game.pitch,game.target.yaw,game.target.pitch)<=game.target.radius;}
function tick(now){
  if(!game)return;
  const dt=Math.max(0,(now-game.last)/1000);game.last=now;
  if(dt>.3&&['running','countdown'].includes(game.phase)){pauseGame();document.exitPointerLock();}
  else if(game.phase==='countdown'){
    game.countdown-=dt;$('#countdown').textContent=game.countdown>0?Math.ceil(game.countdown):'';
    if(game.countdown<=0){game.phase='running';if(game.elapsed===0){game.rng=seeded(game.trial.seed);game.yaw=0;game.pitch=0;if(!game.legacy){game.target={yaw:0,pitch:0,radius:1};game.switchTargets=null;}spawnTarget();}else if(!game.legacy){spawnTarget();}beginAcquisition(game);}
  }else if(game.phase==='running'){
    const activeDt=Math.min(dt,game.trial.seconds-game.elapsed);
    if(activeDt>0){updateTarget(game,game.elapsed);recordSample(game,activeDt);game.elapsed+=activeDt;}
    if(game.elapsed>=game.trial.seconds)finishRound();
  }
  draw();if(game)frame=requestAnimationFrame(tick);
}
function draw(){
  const g=game;if(!g)return;const w=g.w,h=g.h;
  ctx.fillStyle='#161a1e';ctx.fillRect(0,0,w,h);ctx.lineWidth=1;ctx.strokeStyle='#8b98a31b';
  for(let a=-80;a<=80;a+=10){ctx.beginPath();let started=false;for(let p=-40;p<=40;p+=4){const v=project(a,p,g.yaw,g.pitch,w,h);if(v.depth<.15){started=false;continue;}if(!started){ctx.moveTo(v.x,v.y);started=true;}else ctx.lineTo(v.x,v.y);}ctx.stroke();}
  for(let p=-40;p<=40;p+=10){ctx.beginPath();let started=false;for(let a=-80;a<=80;a+=4){const v=project(a,p,g.yaw,g.pitch,w,h);if(v.depth<.15){started=false;continue;}if(!started){ctx.moveTo(v.x,v.y);started=true;}else ctx.lineTo(v.x,v.y);}ctx.stroke();}
  if(g.mode==='calibration'){$('#arena-stats').textContent=fmt(Math.abs(g.calibrationCounts),0)+' unidades de movimento';return;}
  if(g.switchTargets)for(let i=0;i<g.switchTargets.length;i++){if(i===g.switchIndex)continue;const target=g.switchTargets[i],v=project(target.yaw,target.pitch,g.yaw,g.pitch,w,h);if(v.depth>.1){ctx.strokeStyle='#7d898d';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(v.x,v.y,Math.tan(target.radius*Math.PI/180)*v.focal/v.depth,0,Math.PI*2);ctx.stroke();}}
  const t=project(g.target.yaw,g.target.pitch,g.yaw,g.pitch,w,h);
  if(t.depth>.05){const radius=Math.tan(g.target.radius*Math.PI/180)*t.focal/t.depth;ctx.fillStyle=isOnTarget()?'#d2eddf':'#8ac5ac';ctx.beginPath();ctx.arc(t.x,t.y,radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e5f4ec';ctx.lineWidth=1;ctx.stroke();}
  if(t.depth<=.05||t.x<0||t.x>w||t.y<0||t.y>h){ctx.fillStyle='#a9c4b8';ctx.font='13px Segoe UI, sans-serif';ctx.textAlign='center';ctx.fillText('Volte para o alvo',w/2,h/2+55);}
  const x=w/2,y=h/2;ctx.strokeStyle=g.flash<-.1?'#d48b86':'#eef2f0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-10,y);ctx.lineTo(x-4,y);ctx.moveTo(x+4,y);ctx.lineTo(x+10,y);ctx.moveTo(x,y-10);ctx.lineTo(x,y-4);ctx.moveTo(x,y+4);ctx.lineTo(x,y+10);ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(x-1,y-1,2,2);
  if(g.flash>.1){ctx.strokeStyle='#92b9a6';ctx.beginPath();for(const [sx,sy]of[[-1,-1],[1,-1],[-1,1],[1,1]]){ctx.moveTo(x+sx*13,y+sy*13);ctx.lineTo(x+sx*19,y+sy*19);}ctx.stroke();}g.flash*=.85;
  if(performance.now()-g.lastHUD>100){g.lastHUD=performance.now();$('#arena-stats').textContent=Math.ceil(Math.max(0,g.trial.seconds-g.elapsed))+'s   /   '+(isTracking(g.trial.task)?fmt(g.onTargetMs/Math.max(1,g.elapsed*1000)*100,0)+'% no alvo':g.hits+' acertos · '+(g.shots?fmt(g.hits/g.shots*100,0):'—')+'%');}
}
function finishRound(){
  const g=game;if(!g||g.phase!=='running')return;g.phase='finished';document.exitPointerLock();
  const trial={...g.trial,durationMs:round(g.elapsed*1000,1),shots:g.shots,hits:g.hits,onTargetMs:round(g.onTargetMs,1),reactionTimes:g.reactionTimes.map(v=>round(v*1000,1)),angularPath:round(g.path,2),inputMode:g.inputMode,telemetry:g.telemetry};
  const summary=summarizeTrials([trial]),track=isTracking(trial.task),value=track?fmt(summary.onTargetPercent,1)+'%':trial.hits,description=track?'do tempo com a mira no alvo':fmt(summary.accuracy||0,1)+'% de precisão · '+fmt(summary.hitsPerSecond,2)+' acertos/s';
  const detail=track?'Erro médio: '+fmt(summary.meanError,2)+'°':'Aquisição mediana: '+fmt(summary.medianMs||0,0)+' ms';
  if(g.mode==='diagnostic'){
    pending.trials.push(trial);save('pending',pending);const done=pending.trials.length===pending.plan.rounds.length,rest=!done&&pending.trials.length%10===0;
    showOverlay('<div class="eyebrow">RODADA '+pending.trials.length+' / '+pending.plan.rounds.length+'</div><h2>'+ (rest?'Intervalo sugerido':'Rodada concluída')+'</h2><div class="round-metric">'+value+'</div><p>'+description+'</p><p class="caption">'+detail+'</p><div class="progress"><span style="width:'+pending.trials.length/pending.plan.rounds.length*100+'%"></span></div><p>'+(done?'A sessão está completa. Abra o relatório para comparar as condições.':rest?'Descanse por um ou dois minutos. O tempo entre rodadas não entra na análise.':'Continue quando estiver pronto.')+'</p><button class="btn primary" id="next-round">'+(done?'Abrir análise':'Próxima rodada')+'</button>');
    $('#next-round').onclick=()=>done?completeDiagnostic():openDiagnostic();
  }else{
    practiceHistory.unshift({version:2,id:crypto.randomUUID(),createdAt:new Date().toISOString(),profile:{...g.profile},trial});practiceHistory=practiceHistory.slice(0,150);save('practiceHistory',practiceHistory);
    showOverlay('<div class="eyebrow">TREINO REGISTRADO</div><h2>'+LABELS[trial.task]+'</h2><div class="round-metric">'+value+'</div><p>'+description+'</p><p class="caption">'+detail+'</p><p class="caption">'+(track?'':'Eficiência: '+(summary.efficiency==null?'—':fmt(summary.efficiency,1)+'%')+' · ')+fmt(summary.medianFps,0)+' FPS médio</p><div class="actions"><button class="btn primary" id="repeat-practice">Repetir exercício</button><button class="btn ghost" id="end-practice">Voltar</button></div>');
    $('#repeat-practice').onclick=()=>openPractice(trial.task,trial.seconds);$('#end-practice').onclick=closeArena;
  }
}
function completeDiagnostic(){const result=analyze(pending.plan,pending.trials);if(!result){toast('Não foi possível validar as métricas desta sessão. Exporte os dados nas configurações para revisão.');return;}const record={version:pending.plan.version||1,id:crypto.randomUUID(),createdAt:new Date().toISOString(),plan:pending.plan,trials:pending.trials,result};history.unshift(record);history=history.slice(0,100);const persisted=save('history',history);if(persisted){pending=null;save('pending',null);}else{toast('Armazenamento cheio. Exporte a sessão; suas rodadas continuam disponíveis para recuperação.');}lastResult=record;closeArena();location.hash='result/'+record.id;}
function closeArena(){if(game){game.phase='closed';game=null;}cancelAnimationFrame(frame);if(document.pointerLockElement)document.exitPointerLock();$('#countdown').textContent='';dialog.close();render();}
$('#exit-arena').onclick=closeArena;dialog.addEventListener('cancel',e=>{e.preventDefault();if(game&&['running','countdown','calibrating'].includes(game.phase)){pauseGame();document.exitPointerLock();}else closeArena();});
function openCalibration(){game=newGame('calibration',{task:'flick',sens:profile.sens,seconds:0,seed:1},profile);openArena();showOverlay(`<div class="eyebrow">CALIBRAÇÃO FÍSICA</div><h2>Uma régua e seu mouse.</h2><p>Marque 10 cm no mousepad. Posicione o mouse no início, capture o cursor e deslize horizontalmente até a outra marca. Não levante o mouse. Clique para terminar.</p><button class="btn primary" id="start-calibration">Medir movimento ↗</button><p style="font-size:10px;margin-top:15px">A distância real poderá ser informada ao final.</p>`);$('#start-calibration').onclick=startPointer;}
function finishCalibration(){if(!game||game.phase==='finished')return;game.phase='finished';document.exitPointerLock();const counts=Math.abs(game.calibrationCounts);showOverlay(`<div class="eyebrow">MOVIMENTO REGISTRADO</div><h2>${fmt(counts,0)} unidades</h2><p>Informe a distância física que o mouse percorreu em linha reta.</p><label class="field" style="text-align:left;margin-top:20px">Distância em centímetros<input id="measured-cm" type="number" value="10" min="1" max="100" step="0.1"></label><button class="btn primary" id="save-calibration" ${counts<10?'disabled':''}>Calcular e salvar fator</button><p style="font-size:10px;margin-top:12px">${counts<10?'Movimento insuficiente. Feche e repita a medição.':'O fator será (distância ÷ 2,54 × DPI) ÷ unidades registradas.'}</p>`);$('#save-calibration').onclick=()=>{const distance=Number($('#measured-cm').value),factor=round(distance/2.54*profile.dpi/counts);if(distance<1||distance>100||!Number.isFinite(factor)||factor<.1||factor>10){toast('Medição fora do intervalo. Confira a distância e o DPI.');return;}profile.calibration=factor;save('profile',profile);closeArena();toast('Fator '+fmt(factor)+' salvo. Confirme o giro também no Valorant.');};}
render();
